mapper.select:
SELECT id, tenant_id, state_user_id, agent_code, session_id, turn_id, message_id, retrievals, created_at_ms
FROM ai_chat_knowledge_evidence
WHERE tenant_id = #{tenantId}
  AND state_user_id = #{stateUserId}
  AND agent_code = #{agentCode}
  AND session_id = #{sessionId}
  AND message_id = #{messageId}
LIMIT 1
